input.command:
cd /Users/dm/orca/workspaces/HarnessHub/wt-25
python3 -c "
import json
d=json.load(open('plugins/dev-graph/tests/fixtures/live-trial-positive-scenarios.json'))
def walk(o):
    if isinstance(o,dict):
        if o.get('id')=='C14-OUT1-positive-macro-decomposition-r9' or o.get('scenario_id')=='C14-OUT1-positive-macro-decomposition-r9':
            print(json.dumps(o,ensure_ascii=False,indent=2))
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)
" 2>&1 | head -80

