#!/usr/bin/env python3
"""工程4: independent verification of the C14-OUT1 live trial from the persisted graphs."""
import copy
import hashlib
import json
import os
import subprocess
import sys

WT = "/Users/dm/orca/workspaces/HarnessHub/wt-25"
PLUGIN = os.path.join(WT, "plugins/dev-graph")
VALIDATOR = os.path.join(PLUGIN, "scripts/validate-graph-schema.py")
SP = os.path.dirname(os.path.abspath(__file__))
FIX = os.path.join(WT, "eval-log/dev-graph/live-trial-fixtures")

PRE = {
    "beads": {
        "graph_sha256": "a5f9e28deb84777e5ba85992db0c9e3fe232f77174e1f708bc5203fac663f8ef",
        "node_count": 0,
        "graph_revision": 0,
    },
    "none": {
        "graph_sha256": "f0493a6ae3beaf8ebde71c659ca706d1de68200ed34a392bdbdc4a4f9585ccdb",
        "node_count": 0,
        "graph_revision": 0,
    },
}
PRE_FILES = {k: set(open(os.path.join(SP, "pre", f"files-{k}.txt"), encoding="utf-8").read().split())
             for k in PRE}


def sha256_file(p):
    return hashlib.sha256(open(p, "rb").read()).hexdigest()


def digest_excluding_evidence(node):
    payload = {k: v for k, v in node.items() if k != "confirmation_evidence"}
    return hashlib.sha256(
        json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def acyclic(nodes):
    by_id = {n["graph_node_id"]: n for n in nodes}
    edges = {i: [d for d in (by_id[i].get("depends_on") or []) + (by_id[i].get("architecture_refs") or [])
                 if d in by_id] for i in by_id}
    state, cycles = {}, []

    def dfs(u, stack):
        state[u] = 1
        for v in edges[u]:
            if state.get(v) == 1:
                cycles.append(stack[stack.index(v):] + [v] if v in stack else [u, v])
            elif state.get(v) is None:
                dfs(v, stack + [v])
        state[u] = 2

    for n in by_id:
        if state.get(n) is None:
            dfs(n, [n])
    return not cycles, cycles


def validate_stdin(graph_obj, repo_root):
    proc = subprocess.run(
        ["python3", VALIDATOR, "--graph", "-", "--repo-root", repo_root],
        input=json.dumps(graph_obj, ensure_ascii=False), capture_output=True, text=True,
    )
    try:
        return proc.returncode, json.loads(proc.stdout)
    except json.JSONDecodeError:
        return proc.returncode, {"raw": proc.stdout, "err": proc.stderr}


report = {"scenario": "C14-OUT1-positive-macro-decomposition-r9", "runs": {}}

for kind in ("beads", "none"):
    repo = os.path.join(FIX, f"20260807-ci-c14-{kind}")
    gpath = os.path.join(repo, ".dev-graph/state/graph.json")
    graph = json.load(open(gpath, encoding="utf-8"))
    nodes = graph["nodes"]
    features = [n for n in nodes if n["artifact_kind"] == "feature"]
    archs = [n for n in nodes if n["artifact_kind"] == "architecture"]
    tasks = [n for n in nodes if n["artifact_kind"] == "task"]
    fids = {f["graph_node_id"] for f in features}

    # -- observation 1: DAG + granularity ---------------------------------
    ok, cycles = acyclic(nodes)
    per_feature = {f["graph_node_id"]: len([d for d in f.get("depends_on") or [] if d in fids])
                   for f in features}
    obs1 = {
        "feature_count": len(features),
        "architecture_count": len(archs),
        "task_node_count": len(tasks),
        "acyclic": ok,
        "cycles": cycles,
        "metric": "max_inter_feature_depends_on_per_feature",
        "per_feature_inter_feature_depends_on": per_feature,
        "measured_max_value": max(per_feature.values()) if per_feature else 0,
        "declared_max_value": 3,
        "within_threshold": (max(per_feature.values()) if per_feature else 0) <= 3,
    }

    # -- observation 3 + 2: draft gate vs candidate gate -------------------
    def is_candidate(n):
        return (n.get("confirmation_status") == "confirmed"
                and n.get("evaluation_status") == "pass"
                and (n.get("implementation_readiness") or {}).get("status") == "complete")

    candidates = [n["graph_node_id"] for n in features if is_candidate(n)]
    drafts = [n["graph_node_id"] for n in features if not is_candidate(n)]
    draft_detail = {
        n["graph_node_id"]: {
            "status": n["status"],
            "confirmation_status": n["confirmation_status"],
            "evaluation_status": n["evaluation_status"],
            "implementation_readiness": n["implementation_readiness"]["status"],
            "github_publication_mode": n["github_publication"]["mode"],
            "issue_linkage": n["issue_linkage"],
            "beads_linkage": n["beads_linkage"],
            "github_project_linkages": len(n["github_project_linkages"]),
        } for n in features
    }
    obs3 = {
        "candidate_count": len(candidates),
        "candidates": candidates,
        "draft_excluded_count": len(drafts),
        "drafts_excluded": drafts,
        "per_feature_lifecycle": draft_detail,
        "issues_published_by_draft_features": sum(
            1 for n in features if not is_candidate(n) and n["issue_linkage"] is not None),
    }

    # -- observation 4: binding derived from PERSISTED graph ---------------
    persisted_bindings = sorted({n["tracker_binding"] for n in nodes})
    obs4 = {
        "tracker_binding_values_persisted_in_graph": persisted_bindings,
        "node_count_per_persisted_binding": {
            b: sum(1 for n in nodes if n["tracker_binding"] == b) for b in persisted_bindings},
        "derived_from": "graph.json nodes[].tracker_binding (not from the invocation argument)",
    }

    # -- observation 5: write counts by before/after differencing ----------
    now_files = set()
    for root, dirs, fnames in os.walk(repo):
        dirs[:] = [d for d in dirs if d != ".git"]
        for fn in fnames:
            now_files.add("./" + os.path.relpath(os.path.join(root, fn), repo))
    added = sorted(now_files - PRE_FILES[kind])
    removed = sorted(PRE_FILES[kind] - now_files)
    obs5 = {
        "graph_sha256_before": PRE[kind]["graph_sha256"],
        "graph_sha256_after": sha256_file(gpath),
        "graph_changed": sha256_file(gpath) != PRE[kind]["graph_sha256"],
        "node_count_before": PRE[kind]["node_count"],
        "node_count_after": len(nodes),
        "graph_revision_before": PRE[kind]["graph_revision"],
        "graph_revision_after": graph["graph_revision"],
        "local_files_added": added,
        "local_files_removed": removed,
        "local_write_count_by_diff": len(added) + (1 if sha256_file(gpath) != PRE[kind]["graph_sha256"] else 0),
    }

    # -- observation 6: digest recomputation ------------------------------
    obs6 = {}
    for n in features:
        if is_candidate(n):
            rec = digest_excluding_evidence(n)
            stored = n["confirmation_evidence"]["evaluated_digest"]
            obs6[n["graph_node_id"]] = {
                "stored_evaluated_digest": stored,
                "recomputed_from_final_persisted_node": rec,
                "matches": stored == rec,
                "is_placeholder_64_zero": stored == "0" * 64,
                "evaluator": n["confirmation_evidence"]["evaluator"],
                "evidence_ref": n["confirmation_evidence"]["evidence_ref"],
            }

    # -- observation 7: negative controls, in memory, via stdin -----------
    nc = {}
    nc1 = copy.deepcopy(graph)
    tgt = next(n for n in nc1["nodes"] if n["graph_node_id"] == candidates[0])
    tgt["implementation_readiness"] = {"status": "incomplete", "missing_sections": ["受入"],
                                       "checked_at": "2026-08-07T02:00:00Z"}
    rc1, out1 = validate_stdin(nc1, repo)
    nc["evaluation_pass_without_readiness_complete"] = {
        "exit_code": rc1, "rejected": rc1 != 0 and out1.get("valid") is False,
        "violations": [v for v in out1.get("violations", []) if v["node"] == candidates[0]],
    }

    nc2 = copy.deepcopy(graph)
    tgt2 = next(n for n in nc2["nodes"] if n["graph_node_id"] == drafts[0])
    tgt2["status"] = "blocked"
    tgt2["github_publication"] = {"mode": "issue_and_projects", "project_aliases": ["portal"],
                                  "labels": ["macro"], "milestone": None}
    rc2, out2 = validate_stdin(nc2, repo)
    nc["publication_intent_on_blocked_draft_feature"] = {
        "exit_code": rc2, "rejected": rc2 != 0 and out2.get("valid") is False,
        "violations": [v for v in out2.get("violations", []) if v["node"] == drafts[0]],
    }

    rc0, out0 = validate_stdin(graph, repo)
    report["runs"][kind] = {
        "repo_root": repo,
        "repository_id": graph["repository_id"],
        "final_graph_valid": out0.get("valid"),
        "final_graph_violations": out0.get("violations"),
        "observation_1_dag_granularity": obs1,
        "observation_3_draft_and_candidate_gate": obs3,
        "observation_4_binding_from_persisted_graph": obs4,
        "observation_5_write_counts_by_diff": obs5,
        "observation_6_confirmation_evidence_recompute": obs6,
        "observation_7_negative_controls": nc,
    }

with open(os.path.join(SP, "verify-report.json"), "w", encoding="utf-8") as f:
    json.dump(report, f, ensure_ascii=False, indent=2)

for kind, r in report["runs"].items():
    o1 = r["observation_1_dag_granularity"]
    o3 = r["observation_3_draft_and_candidate_gate"]
    o5 = r["observation_5_write_counts_by_diff"]
    o7 = r["observation_7_negative_controls"]
    print(f"[{kind}] valid={r['final_graph_valid']} features={o1['feature_count']} arch={o1['architecture_count']} "
          f"tasks={o1['task_node_count']} acyclic={o1['acyclic']} max_dep={o1['measured_max_value']}<=3:{o1['within_threshold']}")
    print(f"[{kind}] candidates={o3['candidate_count']}{o3['candidates']} drafts_excluded={o3['draft_excluded_count']} "
          f"draft_issues={o3['issues_published_by_draft_features']}")
    print(f"[{kind}] binding_persisted={r['observation_4_binding_from_persisted_graph']['tracker_binding_values_persisted_in_graph']} "
          f"nodes {o5['node_count_before']}->{o5['node_count_after']} rev {o5['graph_revision_before']}->{o5['graph_revision_after']}")
    print(f"[{kind}] digest_ok={ {k: v['matches'] for k, v in r['observation_6_confirmation_evidence_recompute'].items()} }")
    print(f"[{kind}] negctl rejected: {[ (k, v['rejected']) for k, v in o7.items() ]}")
    print()

